#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cstring>

using namespace std;

struct Point {
    int r, c;
    Point(int _r=0, int _c=0): r(_r), c(_c) {}
};

int dr[] = {-1, 0, 0, 1};
int dc[] = {0, -1, 1, 0};

int N, T;
char B[12][12], B1[12][12], B2[12][12];
int D1[12][12], D2[12][12];

void fillDist1(const Point& start) {
    memset(D1, -1, sizeof(D1));
    D1[start.r][start.c] = 0;
    queue<Point> q;
    q.push(start);
    while (!q.empty()) {
        Point p = q.front(); q.pop();
        for (int k=0; k<4; ++k) {
            Point np(p.r + dr[k], p.c + dc[k]);
            if (B[np.r][np.c] != '.') continue;
            if (D1[np.r][np.c] < 0) {
                D1[np.r][np.c] = D1[p.r][p.c] + 1;
                q.push(np);
            }
        }
    }
}

void fillDist2(const Point& start) {
    memset(D2, -1, sizeof(D2));
    D2[start.r][start.c] = 0;
    queue<Point> q;
    q.push(start);
    while (!q.empty()) {
        Point p = q.front(); q.pop();
        if (D1[p.r][p.c] >= 0 && D2[p.r][p.c] >= D1[p.r][p.c]) continue;
        for (int k=0; k<4; ++k) {
            Point np(p.r + dr[k], p.c + dc[k]);
            if (B[np.r][np.c] != '.') continue;
            if (D2[np.r][np.c] < 0) {
                if (D1[np.r][np.c] >= 0 && D1[np.r][np.c] < D2[p.r][p.c] + 1) continue;
                D2[np.r][np.c] = D2[p.r][p.c] + 1;
                q.push(np);
            }
        }
    }
}

struct MF {
    int n;
    vector<vector<int>> cap, flow;
    vector<int> parent, level;

    MF(int size): n(size), cap(size, vector<int>(size,0)), flow(size, vector<int>(size,0)), parent(size), level(size) {}

    void addEdge(int u, int v, int c) {
        cap[u][v] += c;
    }

    int bfs(int s, int t, vector<int>& p) {
        fill(parent.begin(), parent.end(), -1);
        fill(level.begin(), level.end(), -1);
        level[s] = 0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int u=q.front(); q.pop();
            if (u==t) {
                int minCap=INT_MAX;
                for (int v=t; v!=s; v=parent[v]) {
                    minCap = min(minCap, cap[parent[v]][v]-flow[parent[v]][v]);
                }
                p.clear();
                for (int v=t; v!=s; v=parent[v]) p.push_back(v);
                p.push_back(s);
                reverse(p.begin(), p.end());
                return minCap;
            }
            for (int v=0; v<n; ++v) {
                if (parent[v]<0 && cap[u][v]-flow[u][v]>0) {
                    parent[v]=u;
                    level[v]=level[u]+1;
                    q.push(v);
                }
            }
        }
        return 0;
    }

    int maxFlow(int s, int t) {
        int total=0;
        vector<int> p;
        while (int push=bfs(s,t,p)) {
            for (size_t i=0; i+1<p.size(); ++i) {
                int u=p[i], v=p[i+1];
                flow[u][v]+=push;
                flow[v][u]-=push;
            }
            total+=push;
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> T;
    memset(B1, '#', sizeof(B1));
    for (int r=1; r<=N; ++r) {
        cin >> (B1[r]+1);
        B1[r][N+1]='#';
    }
    memset(B2, '#', sizeof(B2));
    for (int r=1; r<=N; ++r) {
        cin >> (B2[r]+1);
        B2[r][N+1]='#';
    }
    memset(B, '#', sizeof(B));
    vector<Point> scientists, capsules;
    Point z;
    for (int r=1; r<=N; ++r) {
        for (int c=1; c<=N; ++c) {
            if (isdigit(B1[r][c])) {
                if (B1[r][c]>'0') scientists.emplace_back(r,c);
                B[r][c]='.';
            } else if (B1[r][c]=='Z') {
                z=Point(r,c);
                B[r][c]='.';
            }
            if (isdigit(B2[r][c]) && B2[r][c]>'0') {
                capsules.emplace_back(r,c);
            }
        }
    }
    fillDist1(z);
    int s=0;
    int t=(int)scientists.size()+(int)capsules.size()+1;
    MF mf(t+1);
    for (int i=0; i<(int)scientists.size(); ++i) {
        mf.addEdge(s, i+1, B1[scientists[i].r][scientists[i].c]-'0');
    }
    for (int j=0; j<(int)capsules.size(); ++j) {
        mf.addEdge((int)scientists.size()+j+1, t, B2[capsules[j].r][capsules[j].c]-'0');
    }
    for (int i=0; i<(int)scientists.size(); ++i) {
        fillDist2(scientists[i]);
        for (int j=0; j<(int)capsules.size(); ++j) {
            if (D2[capsules[j].r][capsules[j].c]>=0 && D2[capsules[j].r][capsules[j].c]<=T)
                mf.addEdge(i+1, (int)scientists.size()+j+1, INT_MAX);
        }
    }
    int res=mf.maxFlow(s,t);
    cout << res << "\n";
    return 0;
}
